/* ❌ OLD: No containment. When the widget's content changes (e.g. a
   feed item updates its height), the engine cannot assume the change
   is local: floats could escape, the widget could grow, and the
   browser may re-run layout for the whole page. */

.widget {
  /* ❌ OLD: nothing scopes the invalidation */
}

.widget__item {
  transition: height 200ms;
}

/* Toggling .widget__item content invalidates the widget AND all
   ancestors' layout regions — costly in a page with hundreds of
   items, because each change re-measures the surrounding layout. */

/* ✅ NEW: contain: content (layout + paint) scopes all internal
   invalidation to the widget's own box. The engine knows nothing
   inside can affect the rest of the page's layout or paint. */

.widget {
  contain: content; /* ✅ NEW: layout + paint containment */
}

.widget__item {
  transition: height 200ms;
}

/* Now an item's height change only dirties the widget's own layout
   and paint region — ancestors are not re-laid-out, and paint is
   clipped to the widget's box. For stable-height feeds, add
   contain: strict or size to also decouple intrinsic sizing. */
